    using (Assert.EnterMultipleScope())
    {
        Assert.That(result.AsBool, Is.False);
        Assert.That(result.Error, Is.EqualTo(TxErrorMessages.TxGasLimitCapExceeded(tx.GasLimit, Eip7825Constants.DefaultTxGasLimitCap)));
    }
}

